/**
 * The rail network for the client: stations (with platforms) and display lines with their stopping patterns.
 * Generated by scripts/build-data.ts into app/data/network.json from data/train/stops.json and lines.json (the
 * pipeline's files and schemas), about 6 KB gz, so station pages, the picker and the stopping-pattern strips work
 * offline and during SSR without another request.
 */
import type { PatternStop } from '@bft/ui'
import data from '../data/network.json'
import { LINE_COLOURS, lineNameFor } from './lineNames.ts'

export interface Station {
  key: string
  name: string
  lat: number
  lon: number
  platforms: Array<{ id: string; code: string }>
}

export interface Pattern {
  route: string
  headsign: string
  dir: number
  trips: number
  stations: string[]
}

export interface DisplayLine {
  name: string
  color: string
  patterns: Pattern[]
}

export const NETWORK_GENERATION: string = data.generation

export const STATIONS: Station[] = data.stations.map((s) => ({
  key: s.k,
  name: s.n,
  lat: s.la,
  lon: s.lo,
  platforms: s.p.map(([id, code]) => ({ id: id as string, code: code as string })),
}))

export const LINES: DisplayLine[] = data.lines.map((l) => ({
  name: l.name,
  color: l.color,
  patterns: l.patterns.map((p) => ({
    route: p.r,
    headsign: p.h,
    dir: p.d,
    trips: p.t,
    stations: p.s.map((i) => (STATIONS[i] as Station).key),
  })),
}))

const byKey = new Map(STATIONS.map((s) => [s.key, s]))
const byPlatform = new Map<string, { station: Station; code: string }>()
for (const s of STATIONS) for (const p of s.platforms) byPlatform.set(p.id, { station: s, code: p.code })

export const stationByKey = (key: string | null | undefined): Station | null =>
  key ? (byKey.get(key) ?? null) : null
export const stationPath = (key: string) => `/station/${key}`

/** Station and platform code for a platform stop id. */
export const platformOf = (stopId: string) => byPlatform.get(stopId) ?? null
export const stationKeyOfStop = (stopId: string): string | null =>
  byPlatform.get(stopId)?.station.key ?? (byKey.has(stopId) ? stopId : null)

/** Stop id → platform code for every platform of a station (MergeOptions.stationPlatforms). */
export const stationPlatforms = (key: string) =>
  new Map((byKey.get(key)?.platforms ?? []).map((p) => [p.id, p.code || undefined]))

const lineByName = new Map(LINES.map((l) => [l.name, l]))

/** The display line a departure belongs to, with its colour. */
export function lineFor(
  route: { short: string; long?: string; color?: string },
  headsign: string,
): DisplayLine {
  const name = lineNameFor(route.long, headsign)
  return (
    lineByName.get(name) ?? {
      name,
      color: LINE_COLOURS[name] ?? route.color ?? '666D8E',
      patterns: [],
    }
  )
}

export interface ReachableGroup {
  line: DisplayLine
  /** e.g. "Springfield Central" (the busiest headsign of the group). */
  towards: string
  stations: Station[]
}

/**
 * Stations reachable from `origin` without changing trains, grouped by display line and direction, in travel order
 * along the busiest pattern of each group (the reachable-only "to" picker, T-Search). Branch stations appear only
 * under the lines that actually serve them.
 */
export function reachableFrom(origin: string): ReachableGroup[] {
  const groups = new Map<string, { line: DisplayLine; heads: Map<string, number>; order: string[] }>()
  for (const line of LINES) {
    for (const p of line.patterns) {
      const i = p.stations.indexOf(origin)
      if (i < 0 || i === p.stations.length - 1) continue
      const gk = `${line.name}|${p.dir}`
      const g = groups.get(gk) ?? { line, heads: new Map<string, number>(), order: [] }
      groups.set(gk, g)
      g.heads.set(p.headsign, (g.heads.get(p.headsign) ?? 0) + p.trips)
      // Patterns are sorted busiest first, so the order follows the main pattern; others' extra stations are
      // inserted after the station they follow.
      let after = -1
      for (const k of p.stations.slice(i + 1)) {
        if (k === origin) continue
        const at = g.order.indexOf(k)
        if (at >= 0) {
          after = at
          continue
        }
        g.order.splice(after + 1, 0, k)
        after += 1
      }
    }
  }
  return [...groups.values()]
    .map((g) => ({
      line: g.line,
      towards: [...g.heads.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? '',
      stations: g.order.map((k) => byKey.get(k)).filter((s): s is Station => !!s),
    }))
    .sort((a, b) => a.line.name.localeCompare(b.line.name) || a.towards.localeCompare(b.towards))
}

export function isReachable(origin: string, dest: string): boolean {
  return LINES.some((l) =>
    l.patterns.some((p) => {
      const i = p.stations.indexOf(origin)
      return i >= 0 && p.stations.indexOf(dest, i + 1) > i
    }),
  )
}

/** Lines whose trains run from `origin` to `dest` directly (search result chips). */
export function linesBetween(origin: string, dest: string): DisplayLine[] {
  return LINES.filter((l) =>
    l.patterns.some((p) => {
      const i = p.stations.indexOf(origin)
      return i >= 0 && p.stations.indexOf(dest, i + 1) > i
    }),
  )
}

/** Is `sub` an ordered subsequence of `seq`? */
function isSubsequence(sub: string[], seq: string[]): boolean {
  let j = 0
  for (const k of seq) if (k === sub[j]) j++
  return j === sub.length
}

export const MAX_STRIP_DOTS = 14

/**
 * Stopping-pattern strip for a departure from `from` (T-Departures): the stations it calls at (`stopsAfter`, station
 * keys) laid on the fullest known pattern of the corridor, so stations an express runs through show as hollow dots.
 * Ends at `to` when given, otherwise at the terminus. Long runs keep the first stations and the end, with a gap.
 * Without `stopsAfter` (an API that doesn't send it) the busiest pattern for the route and headsign is used.
 */
export function stripFor(opts: {
  from: string
  stopsAfter: string[] | null
  route: string
  headsign: string
  to?: string | null
  maxDots?: number
}): PatternStop[] {
  const { from } = opts
  let after = opts.stopsAfter
  if (!after) {
    const p = LINES.flatMap((l) => l.patterns).find(
      (x) => x.route === opts.route && x.headsign === opts.headsign && x.stations.includes(from),
    )
    after = p ? p.stations.slice(p.stations.indexOf(from) + 1) : []
  }
  const endAt = opts.to && after.includes(opts.to) ? after.indexOf(opts.to) : after.length - 1
  const calls = after.slice(0, endAt + 1)
  if (calls.length === 0) return []
  const segment = corridorFor([from, ...calls])
  const callSet = new Set(calls)
  const stops: PatternStop[] = segment.map((k, i) => ({
    id: k,
    name: byKey.get(k)?.name ?? k,
    stops: i === 0 || callSet.has(k),
  }))
  const max = opts.maxDots ?? MAX_STRIP_DOTS
  if (stops.length <= max) return stops
  const last = stops[stops.length - 1] as PatternStop
  return [...stops.slice(0, max - 1), { ...last, gapBefore: true }]
}

/**
 * The fullest known station sequence that starts and ends where `calls` does and contains every station of `calls`
 * in order: the corridor a train with these calls runs along, so the stations it passes can be shown. Falls back to
 * `calls` itself when no pattern covers it.
 */
export function corridorFor(calls: string[]): string[] {
  const first = calls[0]
  const end = calls[calls.length - 1]
  if (!first || !end || calls.length < 2) return calls
  let best: string[] | null = null
  let bestTrips = -1
  for (const l of LINES) {
    for (const p of l.patterns) {
      const i = p.stations.indexOf(first)
      if (i < 0) continue
      const j = p.stations.indexOf(end, i + 1)
      if (j < 0) continue
      const seg = p.stations.slice(i, j + 1)
      if (!isSubsequence(calls, seg)) continue
      if (!best || seg.length > best.length || (seg.length === best.length && p.trips > bestTrips)) {
        best = seg
        bestTrips = p.trips
      }
    }
  }
  return best ?? calls
}

/** Stations an express runs through between here and its end (for "skips 3"). */
export const skippedCount = (strip: PatternStop[]) => strip.filter((s) => !s.stops).length
